steps.script:
var fp = PhaseManager.get_current_phase_instance()
for uid in GameState.state.units:
	if uid != "U_WARBOSS_B" and fp.sequencer_11e.eligible_to_fight(uid, GameState.state):
		fp.sequencer_11e.mark_fought(uid, GameState.state)
return fp.sequencer_11e.eligible_to_fight("U_WARBOSS_B", GameState.state)

for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		t.queue_free()
ToastManager.active_toasts.clear()
return true

for toast in ToastManager.active_toasts:
	if not is_instance_valid(toast):
		continue
	for c in toast.find_children("*", "Label", true, false):
		if "still fighting" in c.text:
			return true
return false
